// Give every player a unique auction ID and deduplicate names across franchises
// (In an auction pool a player can only appear once; we keep the first occurrence)
const seen = new Set();
const AUCTION_POOL = PLAYERS.filter(p => {
  const key = p.name.toLowerCase().trim();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).map((p, idx) => ({ ...p, auctionId: idx + 1 }));

module.exports = { PLAYERS, AUCTION_POOL };
